insert into public.catalog_categories (slug, name, title, subtitle, image_url, sort, translations) values
  ('lareiras', 'Lareiras', 'Lareiras para todos os espaços.', 'A lenha, a gás, elétricas ou a bioetanol — com aconselhamento técnico e instalação incluída.', '/images/orcamento/lareira.jpg', 0, '{"en":{"name":"Fireplaces","title":"Fireplaces for every space.","subtitle":"Wood, gas, electric or bioethanol — with expert advice and installation included."},"es":{"name":"Chimeneas","title":"Chimeneas para todos los espacios.","subtitle":"De leña, gas, eléctricas o de bioetanol — con asesoramiento técnico e instalación incluida."},"fr":{"name":"Cheminées","title":"Des cheminées pour tous les espaces.","subtitle":"À bois, au gaz, électriques ou au bioéthanol — conseil technique et installation compris."},"de":{"name":"Kamine","title":"Kamine für jeden Raum.","subtitle":"Holz, Gas, Strom oder Bioethanol — mit Fachberatung und Montage inklusive."}}'::jsonb),
  ('recuperadores', 'Recuperadores', 'Recupere o calor, poupe na fatura.', 'A lenha ou a pellets, para a lareira que já tem ou para uma construção nova.', '/images/orcamento/recuperador.jpg', 10, '{"en":{"name":"Fireplace inserts","title":"Recover the heat, cut your bills.","subtitle":"Wood or pellet, for the fireplace you already have or for a new build."},"es":{"name":"Insertables","title":"Recupere el calor, ahorre en la factura.","subtitle":"De leña o pellets, para la chimenea que ya tiene o para una obra nueva."},"fr":{"name":"Inserts","title":"Récupérez la chaleur, réduisez la facture.","subtitle":"À bois ou à granulés, pour la cheminée que vous avez déjà ou pour une construction neuve."},"de":{"name":"Kamineinsätze","title":"Wärme zurückgewinnen, Kosten senken.","subtitle":"Für Holz oder Pellets, für Ihren bestehenden Kamin oder einen Neubau."}}'::jsonb),
  ('salamandras', 'Salamandras', 'Calor onde precisa.', 'Salamandras a lenha e a pellets, independentes e fáceis de instalar.', '/images/orcamento/salamandra.jpg', 20, '{"en":{"name":"Stoves","title":"Heat where you need it.","subtitle":"Freestanding wood and pellet stoves, easy to install."},"es":{"name":"Estufas","title":"Calor donde lo necesita.","subtitle":"Estufas de leña y de pellets, independientes y fáciles de instalar."},"fr":{"name":"Poêles","title":"La chaleur là où il faut.","subtitle":"Poêles à bois et à granulés, indépendants et faciles à installer."},"de":{"name":"Öfen","title":"Wärme, wo Sie sie brauchen.","subtitle":"Freistehende Holz- und Pelletöfen, einfach zu installieren."}}'::jsonb),
  ('fogoes', 'Fogões', 'Fogões que aquecem e cozinham.', 'Fogões de cozinha a lenha, entre a tradição e o design atual.', '/images/orcamento/fogao.jpg', 30, '{"en":{"name":"Cookers","title":"Cookers that heat and cook.","subtitle":"Wood-fired kitchen ranges, between tradition and modern design."},"es":{"name":"Cocinas de leña","title":"Cocinas que calientan y cocinan.","subtitle":"Cocinas de leña, entre la tradición y el diseño actual."},"fr":{"name":"Cuisinières","title":"Des cuisinières qui chauffent et qui cuisinent.","subtitle":"Cuisinières à bois, entre tradition et design actuel."},"de":{"name":"Küchenherde","title":"Herde, die heizen und kochen.","subtitle":"Holz-Küchenherde zwischen Tradition und modernem Design."}}'::jsonb),
  ('churrasqueiras', 'Churrasqueiras', 'O exterior merece o melhor.', 'Churrasqueiras a carvão e grelhadores a gás, para os dias em família.', '/images/orcamento/churrasqueira.jpg', 40, '{"en":{"name":"Barbecues","title":"Your garden deserves the best.","subtitle":"Charcoal barbecues and gas grills, for family days outdoors."},"es":{"name":"Barbacoas","title":"El exterior merece lo mejor.","subtitle":"Barbacoas de carbón y parrillas de gas, para los días en familia."},"fr":{"name":"Barbecues","title":"L''extérieur mérite le meilleur.","subtitle":"Barbecues au charbon et grills au gaz, pour les journées en famille."},"de":{"name":"Grills","title":"Draußen nur das Beste.","subtitle":"Holzkohlegrills und Gasgrills für Tage mit der Familie."}}'::jsonb);

